/** Freezes scope and marks a version ready to ship. */
export interface CutVersionRequest {
    /** The moment scope was frozen — the build or tag that cut it. Supplied rather than taken from the
clock, because cutting is often recorded after the fact. Required unless the deprecated
`CutDate` is sent instead. */
    cutAt?: Date | undefined;
    /** The day it was cut, read as 12:00 in the organization's default time zone. */
    cutDate?: string | undefined;
}

/** Cycle-time rollup over a set of completed work items. Carries the underlying count and total so consumers can aggregate across scopes without average-of-averages bias: sum `workItemsCount` and `totalCycleTimeDays` across summaries, then divide the total by the count. */
export interface CycleTimeSummary {
    /** Number of completed work items that contributed to this summary: items
with both an activated and a done timestamp, done after activated. */
    workItemsCount: number;
    /** Sum of cycle times in days across the contributing items.
0 when `workItemsCount` is 0; treat that count, not this field,
as the sign that there is no data. */
    totalCycleTimeDays: number;
    /** Mean cycle time in days, or null when there are no contributing items.
To combine summaries, sum `workItemsCount` and `totalCycleTimeDays`
rather than averaging this value. */
    averageCycleTimeDays?: number | undefined;
}

/** Releases on one day. */
export interface DailyReleaseCountDto {
    date: string;
    released: number;
    /** How many of that day's versions have since been withdrawn. */
    withdrawn: number;
}

/** A Kanban team's metrics for the PI Iteration, measured by the iteration's dates in the team's time zone. Nothing is scoped to an iteration for a Kanban team, so it has no total, committed or not-started figures. */
export interface DateMeasuredTeamMetricsSummary {
    team: NavigationDto;
    /** When the measured window begins: the start of the iteration's first day in the team's time zone that day,
or in its zone on the last day when it has no operating model on the first. */
    from: Date;
    /** When the measured window ends, exclusive: the start of the day after the iteration's last, in
`timeZone`. */
    until: Date;
    /** The IANA time zone the team's operating model has on the iteration's last day. */
    timeZone: string;
    /** The estimate the team is measured in: its sizing method on the iteration's first day, or on its last when
its operating models begin inside the iteration. */
    sizingMethod: SizingMethod;
    /** Requirement-tier items that reached a Done-category status within the window, by done date. Removed work is left out. */
    completedWorkItems: number;
    completedEstimate: number;
    /** Requirement-tier items in an In Progress-category status at `inProgressAsOf`. */
    inProgressWorkItems: number;
    inProgressEstimate: number;
    /** When in progress was read: the window's end for a past iteration, now for the current one, and null for a
future one. */
    inProgressAsOf?: Date | undefined;
    /** Completed and in-progress items with no value in `sizingMethod`. */
    unestimatedWorkItems: number;
    /** Cycle-time rollup of the completed items. */
    cycleTime: CycleTimeSummary;
    /** Whether in progress for a past iteration may be short, because a workspace holding the team's work has not
had its history read through to the end. */
    isHistoryIncomplete: boolean;
}

