export interface ReorderPersonaRequest {
    newOrder: number;
}

/** Puts the tag axes in a given order. */
export interface ReorderProductTagCategoriesRequest {
    /** Every tag category, in the order they should be presented. Must name the whole set: a partial
list would leave the categories it omits at stale positions. */
    orderedCategoryIds: string[];
}

export interface ReorderProjectLifecycleStagesRequest {
    /** The ordered list of stage IDs representing the desired order. */
    orderedStageIds: string[];
}

export interface ReorderScoringModelCriteriaRequest {
    /** The ordered list of criterion IDs representing the desired order. */
    orderedCriterionIds: string[];
}

export interface ReorderScoringModelOutputsRequest {
    /** The ordered list of output IDs representing the desired evaluation order. */
    orderedOutputIds: string[];
}

export interface ReorderScoringScaleLevelsRequest {
    /** The ordered list of rating level IDs representing the desired order. */
    orderedLevelIds: string[];
}

export interface ReorderScoringScalesRequest {
    /** The ordered list of scale IDs representing the desired order. */
    orderedScaleIds: string[];
}

export interface ReorderStepRequest {
    newOrder: number;
}

export interface ReorderStrategicInitiativeKpisRequest {
    /** The ordered list of KPI IDs representing the desired display order. */
    orderedKpiIds: string[];
}

export interface ReorderSwimLaneRequest {
    newOrder: number;
}

export interface ReorderWorkflowStatusesRequest {
    /** Every status of the workflow, in the order wanted. A partial list is refused. */
    orderedStatusIds: string[];
}

export interface ReparentProductRequest {
    /** The unique identifier of the product being moved. */
    id: string;
    /** The new parent, or null to make this a root node. */
    parentId?: string | undefined;
}

export interface ResetPasswordRequest {
    newPassword: string;
}

/** How a resume left the run. */
export interface ResumedImport {
    /** Rows that will be attempted. */
    queuedRowCount: number;
    /** Rows that cannot be, because the retention sweep took their data. */
    skippedRowCount: number;
}

export interface RetypeProductRequest {
    /** The unique identifier of the product. */
    id: string;
    /** The type to move the product onto. */
    productTypeId: string;
}

export interface RevertProjectStatusRequest {
    /** The earlier status to return the Project to. Must be one of the Project's current backward status
targets. */
    toStatus: ProjectStatus;
    /** Why the Project is being reverted. Required — a reversal undoes a decision that had already been
taken, and the explanation is kept in the Project's status history. */
    reason: string;
}

/** Records that a release marked as announced was not in fact announced. */
export interface RevertReleaseRequest {
    /** Why the release was reverted. Required, unlike a withdrawal's reason: this
contradicts what the append-only history already asserts, so the record has to say why. */
    reason: string;
}

/** Records that a version marked as shipped did not in fact ship. */
export interface RevertVersionReleaseRequest {
    /** Why the version is being reverted. Required — this contradicts what the status history already
asserts, so the record has to say why. */
    reason: string;
}

